using UnityEngine;using UnityEngine.AI;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Unity.AI.Navigation;
namespace DeliveryService.Mok.Editor {
[InitializeOnLoad]public static class DistrictBuilder {
const string Dir="Assets/Scripts/Mok/Art/Districts";const string Base="Assets/Synty/PolygonCity/Prefabs/";
static Scene scene;static Transform east,west;static Material concrete,roof,metal,paint,glass;static List<NavMeshBuildSource> westSources;static List<Bounds> westBuildings;static StringBuilder report;static int road,walk;
static DistrictBuilder(){EditorApplication.update+=Poll;}
static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("Temp/Mok-district-build"))return;File.Delete("Temp/Mok-district-build");try{Build();}catch(Exception e){File.WriteAllText("Temp/Mok-district-build.txt",e.ToString());Debug.LogException(e);}}
static Material Mat(string n,Color c){var p=Dir+"/"+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);if(m==null){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,p);}m.color=c;m.SetFloat("_Smoothness",.08f);return m;}
static T Save<T>(T obj,string p)where T:UnityEngine.Object{var old=AssetDatabase.LoadAssetAtPath<T>(p);if(old==null){AssetDatabase.CreateAsset(obj,p);return obj;}EditorUtility.CopySerialized(obj,old);UnityEngine.Object.DestroyImmediate(obj);return old;}
static Bounds BoundsOf(GameObject g){var rr=g.GetComponentsInChildren<Renderer>();var b=rr[0].bounds;foreach(var r in rr)b.Encapsulate(r.bounds);return b;}
static GameObject Box(Transform parent,string n,Vector3 p,Vector3 size,Material m,bool solid=false){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(parent,false);g.transform.position=p;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=m;g.isStatic=true;if(!solid)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
static void Source(List<NavMeshBuildSource> list,Bounds b,int area){list.Add(new NavMeshBuildSource{shape=NavMeshBuildSourceShape.Box,transform=Matrix4x4.TRS(b.center,Quaternion.identity,Vector3.one),size=b.size,area=area});}
static GameObject Place(Transform parent,string path,Vector3 p,float yaw=0,float width=0,float depth=0){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Base+path+".prefab");if(prefab==null)throw new Exception("Missing "+path);var g=(GameObject)PrefabUtility.InstantiatePrefab(prefab,scene);g.transform.SetParent(parent,false);g.transform.SetPositionAndRotation(Vector3.zero,Quaternion.Euler(0,yaw,0));var b=BoundsOf(g);if(width>0){g.transform.localScale=new Vector3(width/b.size.x,1,depth/b.size.z);b=BoundsOf(g);}g.transform.position=p-new Vector3(b.center.x,b.min.y,b.center.z);foreach(var c in g.GetComponentsInChildren<Collider>())c.enabled=false;foreach(var t in g.GetComponentsInChildren<Transform>()){t.gameObject.isStatic=true;t.gameObject.layer=0;}PrefabUtility.RecordPrefabInstancePropertyModifications(g.transform);return g;}
static Bounds Solid(GameObject visual,string name){var b=BoundsOf(visual);var c=new GameObject(name);c.transform.SetParent(visual.transform.parent,false);c.transform.position=b.center;c.AddComponent<BoxCollider>().size=b.size;c.tag="Obstacle";c.isStatic=true;return b;}
// 원래 타일의 UV와 재질을 그대로 유지하면서 렌더러 수만 줄인다.
sealed class Tiles:IDisposable {
readonly GameObject template;readonly Bounds bounds;readonly Dictionary<Material,List<CombineInstance>> parts=new();
public Tiles(string path){template=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(Base+path+".prefab"));template.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);bounds=BoundsOf(template);}
public void Add(float x,float z,float w,float d,float y){var matrix=Matrix4x4.TRS(new Vector3(x,y-bounds.min.y,z),Quaternion.identity,new Vector3(w/bounds.size.x,1,d/bounds.size.z))*Matrix4x4.Translate(new Vector3(-bounds.center.x,0,-bounds.center.z));foreach(var f in template.GetComponentsInChildren<MeshFilter>()){var r=f.GetComponent<MeshRenderer>();if(r==null||f.sharedMesh==null)continue;for(int i=0;i<f.sharedMesh.subMeshCount;i++){var m=r.sharedMaterials[Mathf.Min(i,r.sharedMaterials.Length-1)];if(!parts.ContainsKey(m))parts[m]=new List<CombineInstance>();parts[m].Add(new CombineInstance{mesh=f.sharedMesh,subMeshIndex=i,transform=matrix*f.transform.localToWorldMatrix});}}}
public void Rect(Rect r,float y){for(float x=r.xMin;x<r.xMax-.001f;x+=5)for(float z=r.yMin;z<r.yMax-.001f;z+=5){float w=Mathf.Min(5,r.xMax-x),d=Mathf.Min(5,r.yMax-z);Add(x+w/2,z+d/2,w,d,y);}}
public void Flush(Transform parent,string name){int i=0;foreach(var pair in parts){var mesh=new Mesh{name=name,indexFormat=IndexFormat.UInt32};mesh.CombineMeshes(pair.Value.ToArray(),true,true);mesh=Save(mesh,Dir+"/"+name+"-"+i+".asset");var g=new GameObject(name+" "+i++);g.transform.SetParent(parent,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=pair.Key;g.isStatic=true;}}
public void Dispose(){UnityEngine.Object.DestroyImmediate(template);}}
static void Label(Transform parent,string text,Vector3 p,float yaw,float size){var g=new GameObject(text);g.transform.SetParent(parent,false);g.transform.SetPositionAndRotation(p,Quaternion.Euler(0,yaw,0));var t=g.AddComponent<TextMesh>();t.font=AssetDatabase.LoadAssetAtPath<Font>("Assets/Fonts/BMJUA_ttf.ttf");t.fontSize=64;t.characterSize=size;t.anchor=TextAnchor.MiddleCenter;t.alignment=TextAlignment.Center;t.text=text;t.color=new Color(.92f,.88f,.72f);g.GetComponent<MeshRenderer>().sharedMaterial=t.font.material;}
static void Build(){string stamp=DateTime.Now.ToString("yyyyMMdd-HHmmss");for(int i=0;i<SceneManager.sceneCount;i++)if(!EditorSceneManager.SaveScene(SceneManager.GetSceneAt(i),"Temp/Before-districts-"+stamp+"-"+i+".unity",true))throw new Exception("Backup failed");scene=SceneManager.GetSceneByPath("Assets/Scenes/JJinCity.unity");bool opened=!scene.isLoaded;if(opened)scene=EditorSceneManager.OpenScene("Assets/Scenes/JJinCity.unity",OpenSceneMode.Additive);var previous=SceneManager.GetActiveScene();SceneManager.SetActiveScene(scene);try{
if(!EditorSceneManager.SaveScene(scene,"Temp/JJinCity-before-districts-"+stamp+".unity",true))throw new Exception("Backup failed");east=scene.GetRootGameObjects().First(g=>g.name=="Mok East City").transform;if(east.Find("Street frontage")!=null||scene.GetRootGameObjects().Any(g=>g.name=="Mok West Quarter"))throw new Exception("Already built; preserve user edits");Directory.CreateDirectory(Dir);AssetDatabase.Refresh();report=new StringBuilder();road=NavMesh.GetAreaFromName("Road");walk=NavMesh.GetAreaFromName("SideWalk");concrete=Mat("Old plaster",new Color(.43f,.41f,.34f));roof=Mat("Weathered roof",new Color(.23f,.29f,.28f));metal=Mat("Dark steel",new Color(.13f,.17f,.18f));paint=Mat("Faded yellow",new Color(.68f,.52f,.23f));glass=Mat("Window dark",new Color(.08f,.15f,.17f));
ImproveEast();BuildWest();FitBackground();AssetDatabase.SaveAssets();Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Save failed");File.WriteAllText("Temp/Mok-district-build.txt",report.ToString());
}finally{SceneManager.SetActiveScene(previous);if(opened)EditorSceneManager.CloseScene(scene,true);}}
static void ImproveEast(){var detail=new GameObject("Street frontage").transform;detail.SetParent(east,false);var roadRects=new List<Rect>();var walkRects=new List<Rect>();var sources=new List<NavMeshBuildSource>();foreach(Transform t in east){if(t.name=="North south avenue"||t.name=="East west avenue"){var size=t.lossyScale;roadRects.Add(new Rect(t.position.x-size.x/2,t.position.z-size.z/2,size.x,size.z));Source(sources,new Bounds(t.position,size),road);t.GetComponent<Renderer>().enabled=false;}else if(t.name=="Block pavement"||t.name.Contains("promenade")){var size=t.lossyScale;walkRects.Add(new Rect(t.position.x-size.x/2,t.position.z-size.z/2,size.x,size.z));Source(sources,new Bounds(t.position,size),walk);t.GetComponent<Renderer>().enabled=false;}else if(t.name=="Building collision"){Source(sources,t.GetComponent<Collider>().bounds,1);}}
// 교차로에서는 같은 타일을 중복으로 그리지 않는다.
using(var tiles=new Tiles("Environments/SM_Env_Road_Bare_01")){var xx=Enumerable.Range(0,53).Select(i=>195+i*5f).Concat(roadRects.SelectMany(r=>new[]{r.xMin,r.xMax})).Distinct().OrderBy(x=>x).ToArray();var zz=Enumerable.Range(0,51).Select(i=>-130+i*5f).Concat(roadRects.SelectMany(r=>new[]{r.yMin,r.yMax})).Distinct().OrderBy(x=>x).ToArray();for(int i=0;i<xx.Length-1;i++)for(int j=0;j<zz.Length-1;j++){float x=(xx[i]+xx[i+1])/2,z=(zz[j]+zz[j+1])/2;if(roadRects.Any(r=>r.Contains(new Vector2(x,z))))tiles.Add(x,z,xx[i+1]-xx[i],zz[j+1]-zz[j],.003f);}tiles.Flush(detail,"East asphalt tiles");}
using(var tiles=new Tiles("Environments/SM_Env_Sidewalk_01")){foreach(var r in walkRects)tiles.Rect(r,.05f);tiles.Flush(detail,"East pavement tiles");}
foreach(var t in east.GetComponentsInChildren<Transform>().Where(t=>t.name=="Pavement seam"))t.gameObject.SetActive(false);
float[] xs={210,290,370,440},zs={-110,-5,100};int shops=0;for(int i=0;i<3;i++)for(int j=0;j<2;j++)foreach(int side in new[]{-1,1}){float left=xs[i]+6,right=xs[i+1]-6,z=side<0?zs[j]+11:zs[j+1]-11;for(float x=left+7;x<right-4;x+=11){var g=Place(detail,"Buildings/SM_Bld_Shop_0"+(1+shops%6),new Vector3(x,.05f,z),side<0?0:180,9,5);g.name="East shop frontage "+(++shops);Source(sources,Solid(g,"Shop collision"),1);if(shops%3==0)Place(detail,"Props/SM_Prop_Aircon_01",new Vector3(x+3.8f,3.2f,z),0);}
for(float x=left+10;x<right-5;x+=23){Place(detail,"Props/SM_Prop_TrashCan_01",new Vector3(x,.1f,z+side*3.9f));Place(detail,"Props/SM_Prop_ParkBench_01",new Vector3(x+3,.1f,z+side*3.9f),side<0?180:0);}}
// 생활 소품과 작은 주차 구역으로 큰 빈 공간을 나눈다.
foreach(float z in new[]{-120f,110f})for(float x=225;x<440;x+=27){Place(detail,"Environments/SM_Env_Tree_01",new Vector3(x,.05f,z));Place(detail,"Props/SM_Prop_Trashbin_01",new Vector3(x+3,.05f,z));}
InstallNav(east,sources,new Bounds(new Vector3(325,35,-5),new Vector3(262,80,252)),"East detail navigation");report.AppendLine("East: original road/pavement tile meshes and materials; "+shops+" shop fronts; street furniture; navigation rebuilt.");}
static void BuildWest(){west=new GameObject("Mok West Quarter").transform;westSources=new List<NavMeshBuildSource>();westBuildings=new List<Bounds>();
Box(west,"Quarter foundation",new Vector3(-280,-2.1f,-5),new Vector3(170,4,160),concrete,true);var ground=Box(west,"Quarter walkable floor",new Vector3(-280,-.08f,-5),new Vector3(170,.16f,160),concrete,true);ground.GetComponent<Renderer>().enabled=false;Source(westSources,ground.GetComponent<Collider>().bounds,walk);
var apron=Box(west,"Bridge parking approach",new Vector3(-175,-.08f,-5),new Vector3(40,.16f,30),concrete,true);apron.GetComponent<Renderer>().enabled=false;Source(westSources,apron.GetComponent<Collider>().bounds,road);
using(var tiles=new Tiles("Environments/SM_Env_Road_Bare_01")){tiles.Rect(new Rect(-195,-20,40,30),.003f);tiles.Flush(west,"West parking asphalt");}
using(var tiles=new Tiles("Environments/SM_Env_Sidewalk_01")){tiles.Rect(new Rect(-365,-85,170,160),.003f);tiles.Flush(west,"West alley paving");}
int number=0;float[] zRows={-65,-45,-25,15,35,55};for(int col=0;col<8;col++)foreach(float z in zRows){float x=-209-col*19;BuildHouse(new Vector3(x,0,z),1+(number%3),number++);}
// 골목 중앙의 작은 상점과 차양. 통로는 최소 4m 이상 확보한다.
for(int i=0;i<7;i++){float x=-218-i*19;foreach(int sign in new[]{-1,1}){var stall=Place(west,"Buildings/SM_Bld_Shop_0"+(1+i%6),new Vector3(x,.04f,-5+sign*9),sign<0?180:0,8,4);var b=Solid(stall,"Market shop collision");Source(westSources,b,1);westBuildings.Add(b);Box(west,"Faded awning",new Vector3(x,3.15f,-5+sign*6.5f),new Vector3(8,.15f,2),i%2==0?roof:paint);}}
foreach(float z in new[]{-84.5f,74.5f}){var g=Box(west,"Quarter perimeter wall",new Vector3(-280,1.1f,z),new Vector3(170,2.2f,1),concrete,true);g.tag="Obstacle";Source(westSources,g.GetComponent<Collider>().bounds,1);}var back=Box(west,"Quarter back wall",new Vector3(-364.5f,1.1f,-5),new Vector3(1,2.2f,160),concrete,true);back.tag="Obstacle";Source(westSources,back.GetComponent<Collider>().bounds,1);
foreach(int side in new[]{-1,1}){var g=Box(west,"Quarter entrance wing",new Vector3(-195,1.1f,-5+side*45),new Vector3(1,2.2f,70),concrete,true);g.tag="Obstacle";Source(westSources,g.GetComponent<Collider>().bounds,1);}
// 보행자는 통과하고 오토바이 충돌체만 막는 입구 경계. 전역 충돌 설정은 바꾸지 않는다.
var gate=new GameObject("Motorcycle entry barrier");gate.transform.SetParent(west,false);gate.transform.position=new Vector3(-195,1.5f,-5);gate.layer=2;var barrier=gate.AddComponent<BoxCollider>();barrier.size=new Vector3(.5f,3,20);barrier.excludeLayers=~(1<<12);barrier.includeLayers=1<<12;barrier.layerOverridePriority=100;
for(int i=0;i<7;i++){float z=-14+i*3;Box(west,"Pedestrian bollard",new Vector3(-195,.55f,z),new Vector3(.35f,1.1f,.35f),metal);Box(west,"Bollard reflector",new Vector3(-195,.85f,z),new Vector3(.37f,.16f,.37f),paint);}
Box(west,"Entrance sign beam",new Vector3(-195,3.6f,-5),new Vector3(.4f,.65f,19),metal);Label(west,"서안 골목",new Vector3(-194.76f,3.65f,-5),90,.14f);Label(west,"도보 전용 · 오토바이는 입구에 주차",new Vector3(-194.75f,3.25f,-5),90,.055f);
for(int i=0;i<5;i++){float x=-160-i*5;Box(west,"Parking bay line",new Vector3(x,.025f,5),new Vector3(.08f,.02f,4),paint);}
Label(west,"오토바이 주차",new Vector3(-174,1.6f,9),180,.09f);Box(west,"Parking sign back",new Vector3(-174,1.6f,9.05f),new Vector3(5,.75f,.1f),metal);
var anchor=new GameObject("Motorcycle parking");anchor.transform.SetParent(west,false);anchor.transform.position=new Vector3(-176,.1f,4);var place=anchor.AddComponent<DeliveryService.Mok.Navigation.NavigationPlace>();place.placeId="west-parking";place.displayName="서안 골목 입구";place.kind=DeliveryService.Mok.Navigation.NavigationPlaceKind.Other;place.mapAnchor=anchor.transform;place.entrance=anchor.transform;
InstallNav(west,westSources,new Bounds(new Vector3(-260,20,-5),new Vector3(214,50,164)),"West quarter navigation");var nav=west.GetComponentInChildren<NavMeshSurface>();var link=nav.gameObject.AddComponent<NavMeshLink>();link.startPoint=new Vector3(-150,.1f,-5);link.endPoint=new Vector3(-161,.1f,-5);link.width=8;link.area=road;link.bidirectional=true;link.UpdateLink();BuildWestMap();report.AppendLine("West: 48 low-rise houses, 14 market shops, alley routes, parking, motorcycle-only entry barrier, map and navigation.");}
static void BuildHouse(Vector3 p,int floors,int number){float height=floors*3;var group=new GameObject("West house "+(number+1).ToString("00")).transform;group.SetParent(west,false);var body=Box(group,"House walls",p+new Vector3(0,height/2,0),new Vector3(14,height,15),concrete,true);body.tag="Obstacle";Source(westSources,body.GetComponent<Collider>().bounds,1);westBuildings.Add(body.GetComponent<Collider>().bounds);
float face=p.z< -5?1:-1;for(int story=0;story<floors;story++)for(int k=-1;k<=1;k++){var g=Place(group,"Buildings/SM_Bld_Apartment_01",p+new Vector3(k*4.5f,story*3,face*5),face<0?0:180,4.5f,5);if(number%3!=0){var material=AssetDatabase.LoadAssetAtPath<Material>("Assets/Synty/PolygonCity/Materials/Alts/PolygonCity_01_"+(number%3==1?"B":"C")+".mat");foreach(var r in g.GetComponentsInChildren<Renderer>()){var mats=r.sharedMaterials;for(int m=0;m<mats.Length;m++)if(mats[m].name.StartsWith("PolygonCity_01_"))mats[m]=material;r.sharedMaterials=mats;PrefabUtility.RecordPrefabInstancePropertyModifications(r);}}}
Box(group,"Patched roof",p+new Vector3(0,height+.12f,0),new Vector3(14.5f,.24f,15.5f),number%2==0?roof:concrete);for(int k=-6;k<=6;k+=2)Box(group,"Roof seams",p+new Vector3(k,height+.26f,0),new Vector3(.08f,.04f,15.4f),metal);
// 측면 창과 생활 흔적을 넣어 골목에서도 빈 상자처럼 보이지 않게 한다.
foreach(int side in new[]{-1,1})for(int story=0;story<floors;story++)foreach(float z in new[]{-4f,1f,5f}){Box(group,"Side window frame",p+new Vector3(side*7.03f,story*3+1.6f,z),new Vector3(.09f,1.4f,1.2f),metal);Box(group,"Side window",p+new Vector3(side*7.09f,story*3+1.6f,z),new Vector3(.03f,1.15f,.95f),glass);}
if(number%3==0)Place(group,"Props/SM_Prop_Roof_Aircon_01",p+new Vector3(3,height+.25f,2));Place(group,"Props/SM_Prop_TrashBag_0"+(1+number%3),p+new Vector3(7.5f,.04f,5));if(number%2==0)Place(group,"Props/SM_Prop_CardboardBox_01",p+new Vector3(7.5f,.04f,3));
var entry=new GameObject("West entrance "+(number+1).ToString("00"));entry.transform.SetParent(west,false);entry.transform.position=p+new Vector3(0,.1f,face*8.5f);
}
static void InstallNav(Transform parent,List<NavMeshBuildSource> sources,Bounds bounds,string name){var data=NavMeshBuilder.BuildNavMeshData(NavMesh.GetSettingsByIndex(0),sources,bounds,Vector3.zero,Quaternion.identity);data=Save(data,Dir+"/"+name+".asset");var surface=parent.GetComponentInChildren<NavMeshSurface>();if(surface==null){var g=new GameObject(name);g.transform.SetParent(parent,false);surface=g.AddComponent<NavMeshSurface>();}surface.RemoveData();surface.navMeshData=data;surface.AddData();}
static void BuildWestMap(){var verts=new List<Vector3>();var indices=new[]{new List<int>(),new List<int>(),new List<int>()};void Quad(Bounds b,int type,float y){int n=verts.Count;verts.AddRange(new[]{new Vector3(b.min.x,y,b.min.z),new Vector3(b.min.x,y,b.max.z),new Vector3(b.max.x,y,b.max.z),new Vector3(b.max.x,y,b.min.z)});indices[type].AddRange(new[]{n,n+1,n+2,n,n+2,n+3});}Quad(new Bounds(new Vector3(-280,0,-5),new Vector3(170,0,160)),0,-.15f);Quad(new Bounds(new Vector3(-175,0,-5),new Vector3(40,0,30)),1,0);foreach(var b in westBuildings)Quad(b,2,.15f);var mesh=new Mesh{name="West quarter map",indexFormat=IndexFormat.UInt32};mesh.SetVertices(verts);mesh.subMeshCount=3;for(int i=0;i<3;i++)mesh.SetTriangles(indices[i],i);mesh.RecalculateBounds();mesh=Save(mesh,Dir+"/West map.asset");var go=new GameObject("West flat navigation map");go.transform.SetParent(west,false);go.layer=20;go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterials=new[]{"Ground","Roads","Buildings"}.Select(n=>AssetDatabase.LoadAssetAtPath<Material>("Assets/Scripts/Mok/Art/NavigationMap/"+n+".mat")).ToArray();}
static void FitBackground(){var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();foreach(var t in all.Where(t=>t.name=="SM_Env_Skyline_01")){t.position+=new Vector3(-95,0,0);t.localScale=new Vector3(t.localScale.x*1.2f,t.localScale.y,t.localScale.z*1.2f);PrefabUtility.RecordPrefabInstancePropertyModifications(t);}var camera=all.First(t=>t.name=="NavigationOverviewCamera").GetComponent<Camera>();camera.transform.position=new Vector3(45,80,-5);camera.orthographicSize=280;}
}}
